import type { PolygonHoldCandidate } from '../../types'

// Generated from the 7292×5514 canonical wall image by tools/detect_holds.py.
// Coordinates are quantized to uint16 and packed to keep the bootstrap dataset small.
// This is still auto-generated candidate data, not ground truth.
const PACKED = ''

const kindNames = ['hold', 'macro', 'volume'] as const

function decodePackedCandidates(): PolygonHoldCandidate[] {
  const raw = atob(PACKED)
  const bytes = Uint8Array.from(raw, (char) => char.charCodeAt(0))
  const view = new DataView(bytes.buffer)
  const holds: PolygonHoldCandidate[] = []
  let offset = 0
  let index = 1

  const readU16 = () => {
    const value = view.getUint16(offset, true)
    offset += 2
    return value / 65535
  }

  while (offset < bytes.length) {
    const kind = kindNames[view.getUint8(offset++)]
    const vertexCount = view.getUint8(offset++)
    const center: [number, number] = [readU16(), readU16()]
    const polygon: [number, number][] = []
    for (let i = 0; i < vertexCount; i += 1) polygon.push([readU16(), readU16()])

    holds.push({
      id: `h${String(index).padStart(3, '0')}`,
      center,
      polygon,
      kind,
    })
    index += 1
  }

  return holds
}

export const polygonCandidates = decodePackedCandidates()
export const polygonById = new Map(polygonCandidates.map((hold) => [hold.id, hold] as const))
